// Package generated decides which files of a diff are not worth reviewing:
// lock files, codegen output, ORM migration snapshots, minified bundles and
// vendored code. clump does not send their hunks to the model; it puts them
// in a "Generated files" group that the TUI shows folded.
//
// A file is generated when, in this order of precedence:
//
//  1. it matches a `review` pattern from the config: never generated;
//  2. .gitattributes sets linguist-generated or linguist-vendored on it
//     (GitHub's own switch), or unsets them (then it is never generated);
//  3. it matches a `patterns` entry from the config;
//  4. it matches a Builtin pattern (unless `builtin = false`);
//  5. a line near the top of the file carries a generator marker such as
//     "Code generated ... DO NOT EDIT." or "@generated", or a .sql file
//     carries drizzle-kit's "--> statement-breakpoint", or a .json file
//     opens like a drizzle-kit snapshot ("dialect" and "prevId(s)").
package generated

import (
	"bytes"
	"context"
	"os/exec"
	"path"
	"regexp"
	"strconv"
	"strings"

	"github.com/k22i/clump/internal/gitdiff"
)

// Options configures a Detector (the [generated] table of the config).
type Options struct {
	// Detect turns detection on. When false Mark clears every file.
	Detect bool
	// Builtin adds the Builtin patterns.
	Builtin bool
	// Patterns are extra paths to skip.
	Patterns []string
	// Review are paths that are always reviewed.
	Review []string
}

// Detector marks generated files. It is safe for concurrent use.
type Detector struct {
	on       bool
	review   []Pattern
	patterns []Pattern
	builtin  []Pattern
	// checkAttr runs `git check-attr`; replaced in tests.
	checkAttr func(ctx context.Context, repo string, paths []string) (map[string]attrState, error)
}

// New compiles o. Patterns were validated with the config, so an error here
// means a caller skipped validation.
func New(o Options) (*Detector, error) {
	d := &Detector{on: o.Detect, checkAttr: gitCheckAttr}
	var err error
	if d.review, err = CompileAll(o.Review); err != nil {
		return nil, err
	}
	if d.patterns, err = CompileAll(o.Patterns); err != nil {
		return nil, err
	}
	if o.Builtin {
		if d.builtin, err = CompileAll(Builtin); err != nil {
			return nil, err
		}
	}
	return d, nil
}

// markerLines is how far into a file a generator marker is looked for.
const markerLines = 10

// Generator markers, matched against lines near the top of a file.
var (
	// "Code generated by protoc-gen-go. DO NOT EDIT." (the Go convention,
	// also sqlc, gqlgen, ent, stringer, oapi-codegen), "This file is
	// generated; do not modify", "AUTOGENERATED FILE - DO NOT EDIT".
	doNotEditRe = regexp.MustCompile(`(?i)generated.*\b(do not|don't|dont) (edit|modify)\b|\b(do not|don't|dont) (edit|modify)\b.*generated`)
	// "@generated" (Relay, Buck, Cargo.lock, Meta tooling), "<auto-generated>"
	// (.NET), "This file is automatically generated", "Autogenerated by Thrift".
	markerRe = regexp.MustCompile(`@generated\b|(?i)<auto-generated|\bauto-?generated\b|\bautomatically generated\b|\bgenerated automatically\b`)
	// drizzle-kit writes this between statements of every migration.
	drizzleRe = regexp.MustCompile(`^--> statement-breakpoint\s*$`)
	// drizzle-kit snapshots open with "dialect" and "prevId" (v0) or
	// "prevIds" (v1) among their first keys.
	snapDialectRe = regexp.MustCompile(`^\s*"dialect"\s*:`)
	snapPrevRe    = regexp.MustCompile(`^\s*"prevIds?"\s*:`)
)

// Mark sets File.Generated on every file of d (clearing it on the others).
// repo is the repository root for .gitattributes ("" skips that check);
// a git failure only skips that check.
func (det *Detector) Mark(ctx context.Context, d *gitdiff.Diff, repo string) {
	if d == nil {
		return
	}
	for _, f := range d.Files {
		f.Generated = ""
	}
	if det == nil || !det.on || len(d.Files) == 0 {
		return
	}
	var attrs map[string]attrState
	if repo != "" && det.checkAttr != nil {
		paths := make([]string, 0, len(d.Files))
		for _, f := range d.Files {
			paths = append(paths, f.Path())
		}
		attrs, _ = det.checkAttr(ctx, repo, paths)
	}
	for _, f := range d.Files {
		f.Generated = det.reason(f, attrs[f.Path()])
	}
}

// reason is why f is generated, or "".
func (det *Detector) reason(f *gitdiff.File, attr attrState) string {
	p := f.Path()
	if _, ok := firstMatch(det.review, p); ok {
		return ""
	}
	switch attr {
	case attrGenerated:
		return "linguist-generated"
	case attrVendored:
		return "linguist-vendored"
	case attrReviewed:
		return ""
	}
	if m, ok := firstMatch(det.patterns, p); ok {
		return "pattern " + m.Text
	}
	if m, ok := firstMatch(det.builtin, p); ok {
		return "pattern " + m.Text
	}
	return markerReason(f)
}

// markerReason looks for a generator marker in the lines of f that are
// visible in the diff near the top of the file (old or new side).
func markerReason(f *gitdiff.File) string {
	ext := path.Ext(f.Path())
	sql := strings.EqualFold(ext, ".sql")
	json := strings.EqualFold(ext, ".json")
	var dialect, prev bool
	for _, h := range f.Hunks {
		if h.Pseudo {
			continue
		}
		oldNo, newNo := h.OldStart, h.NewStart
		for _, raw := range h.Lines {
			prefix, text := " ", ""
			if raw != "" {
				prefix, text = raw[:1], raw[1:]
			}
			top := false
			switch prefix {
			case "-":
				top = oldNo <= markerLines
				oldNo++
			case "+":
				top = newNo <= markerLines
				newNo++
			case "\\":
				continue
			default:
				top = oldNo <= markerLines || newNo <= markerLines
				oldNo++
				newNo++
			}
			if sql && drizzleRe.MatchString(text) {
				return "marker statement-breakpoint (drizzle)"
			}
			if json && top {
				dialect = dialect || snapDialectRe.MatchString(text)
				prev = prev || snapPrevRe.MatchString(text)
				if dialect && prev {
					return "marker snapshot (drizzle)"
				}
			}
			if !top || !isComment(text) {
				continue
			}
			if doNotEditRe.MatchString(text) {
				return "marker DO NOT EDIT"
			}
			if m := markerRe.FindString(text); m != "" {
				return "marker " + strings.TrimPrefix(m, "<")
			}
		}
	}
	return ""
}

// commentStarts are the comment leaders a marker line must start with, so
// that a string literal mentioning "@generated" in a handwritten file does
// not count.
var commentStarts = []string{"//", "#", "/*", "*", "--", "<!--", ";", "%", `"""`, "'''", "{-", "(*"}

// isComment reports whether a line, after leading blanks, starts a comment.
func isComment(text string) bool {
	t := strings.TrimLeft(text, " \t")
	for _, c := range commentStarts {
		if strings.HasPrefix(t, c) {
			return true
		}
	}
	return false
}

// attrState is what .gitattributes says about a path.
type attrState int

const (
	attrNone      attrState = iota // unspecified
	attrGenerated                  // linguist-generated set
	attrVendored                   // linguist-vendored set
	attrReviewed                   // either unset or false: never generated
)

// gitCheckAttr asks git for linguist-generated and linguist-vendored on paths.
func gitCheckAttr(ctx context.Context, repo string, paths []string) (map[string]attrState, error) {
	var in bytes.Buffer
	for _, p := range paths {
		in.WriteString(p)
		in.WriteByte(0)
	}
	cmd := exec.CommandContext(ctx, "git", "-C", repo, "check-attr", "-z", "--stdin", "linguist-generated", "linguist-vendored")
	cmd.Stdin = &in
	out, err := cmd.Output()
	if err != nil {
		return nil, err
	}
	return parseCheckAttr(out), nil
}

// parseCheckAttr reads `git check-attr -z` output: NUL-separated
// path, attribute, value triples. A set attribute wins over an unset one.
func parseCheckAttr(out []byte) map[string]attrState {
	parts := strings.Split(string(out), "\x00")
	res := map[string]attrState{}
	for i := 0; i+2 < len(parts); i += 3 {
		p, attr, val := parts[i], parts[i+1], parts[i+2]
		var st attrState
		switch val {
		case "set", "true":
			st = attrGenerated
			if attr == "linguist-vendored" {
				st = attrVendored
			}
		case "unset", "false":
			st = attrReviewed
		default:
			continue
		}
		cur := res[p]
		if cur == attrNone || cur == attrReviewed {
			res[p] = st
		}
	}
	return res
}

// Signature names the generated files of d by index ("" when there are
// none). It goes into the result cache key, because the grouping depends on
// what was left out of the prompt.
func Signature(d *gitdiff.Diff) string {
	var b strings.Builder
	for i, f := range d.Files {
		if f.Generated == "" {
			continue
		}
		if b.Len() > 0 {
			b.WriteByte(',')
		}
		b.WriteString(strconv.Itoa(i))
	}
	return b.String()
}
